import Foundation
@testable import JavaIntelligence
import XCTest

/// `xccov view` JSON from a real `xcodebuild test -enableCodeCoverage YES` run of the app
/// template (`Fixtures/XcodeTests/XCCovArchive.json` + `XCCovReport.json`, regenerated by the
/// `XCCOV_FIXTURES=1` coverage flow test; machine paths sanitized to `/example`).
final class XCCovArchiveParserTests: XCTestCase {
    private func report(includeTests: Bool = true) throws -> JavaCoverageReport {
        try XCCovArchiveParser.parse(
            archive: Data(contentsOf: XcodeFixtures.url("XCCovArchive.json")),
            report: Data(contentsOf: XcodeFixtures.url("XCCovReport.json")),
            name: "ProbeAppTests",
            options: .init(
                projectRoot: URL(fileURLWithPath: "/example/ProbeApp"), includeTests: includeTests
            )
        )
    }

    func testATargetIsAPackageAndAFileIsAClass() throws {
        let parsed = try report()
        XCTAssertEqual(parsed.packages.map(\.name), ["Tests"])
        let package = try XCTUnwrap(parsed.packages.first)
        XCTAssertEqual(package.sourceFiles.map(\.name), ["ProbeAppTests.swift"])
        XCTAssertEqual(package.classes.map(\.displayName), ["ProbeAppTests"])
        XCTAssertEqual(
            package.sourceFiles.first?.url,
            URL(fileURLWithPath: "/example/ProbeApp/Tests/ProbeAppTests.swift"))
        XCTAssertEqual(parsed.name, "ProbeAppTests")
    }

    func testLinesCountFromTheArchiveAndTotalsFromTheReport() throws {
        let parsed = try report()
        let file = try XCTUnwrap(parsed.packages.first?.sourceFiles.first)
        // Lines 1-3 and 7 have no code; the rest ran.
        XCTAssertEqual(file.lines.map(\.number), [4, 5, 6, 8, 9, 10, 11, 12])
        XCTAssertTrue(file.lines.allSatisfy { $0.status == .covered })
        XCTAssertEqual(parsed.totals.lines, JavaCoverageCounter(missed: 0, covered: 8))
        // Six functions, all with a count; the file's own line counters back instructions.
        XCTAssertEqual(parsed.totals.methods, JavaCoverageCounter(missed: 0, covered: 6))
        XCTAssertEqual(parsed.totals.instructions, JavaCoverageCounter(missed: 0, covered: 14))
    }

    func testFilesUnderTestsStayOutUnlessAskedFor() throws {
        XCTAssertThrowsError(
            try XCCovArchiveParser.parse(
                archive: Data(contentsOf: XcodeFixtures.url("XCCovArchive.json")),
                report: Data(contentsOf: XcodeFixtures.url("XCCovReport.json")),
                name: "ProbeAppTests",
                options: .init(projectRoot: URL(fileURLWithPath: "/example/ProbeApp")))
        ) { XCTAssertEqual($0 as? XCCovArchiveParser.ParseError, .noFiles) }
    }

    func testASubrangeThatNeverRanIsPartial() throws {
        let archive = """
        {"/example/ProbeApp/ProbeApp/ContentView.swift": [
          {"line": 10, "isExecutable": true, "executionCount": 3},
          {"line": 11, "isExecutable": true, "executionCount": 3,
           "subranges": [{"column": 1, "executionCount": 3, "length": 10},
                         {"column": 12, "executionCount": 0, "length": 5}]},
          {"line": 12, "isExecutable": true, "executionCount": 0},
          {"line": 13, "isExecutable": false}
        ]}
        """.data(using: .utf8)!
        let parsed = try XCCovArchiveParser.parse(
            archive: archive, report: nil, name: "P",
            options: .init(projectRoot: URL(fileURLWithPath: "/example/ProbeApp")))
        let file = try XCTUnwrap(parsed.packages.first?.sourceFiles.first)
        XCTAssertEqual(file.lines.map(\.status), [.covered, .partial, .missed])
        // No report, so no function data: only the lines counter is filled.
        XCTAssertEqual(parsed.totals.lines, JavaCoverageCounter(missed: 1, covered: 2))
        XCTAssertEqual(parsed.totals.methods, JavaCoverageCounter())
    }

    func testForeignFilesAndBadDataAreRefused() throws {
        let elsewhere = """
        {"/other/place/Foo.swift": [{"line": 1, "isExecutable": true, "executionCount": 1}]}
        """.data(using: .utf8)!
        XCTAssertThrowsError(
            try XCCovArchiveParser.parse(
                archive: elsewhere, report: nil, name: "P",
                options: .init(projectRoot: URL(fileURLWithPath: "/example/ProbeApp")))
        ) { XCTAssertEqual($0 as? XCCovArchiveParser.ParseError, .noFiles) }
        XCTAssertThrowsError(
            try XCCovArchiveParser.parse(
                archive: Data("not json".utf8), report: nil, name: "P", options: .init())
        ) { XCTAssertEqual($0 as? XCCovArchiveParser.ParseError, .notCoverageData) }
    }
}
